import math
def taxa(passo, maxima=3e-4, aquecer=100, total=1000):
    if passo < aquecer:
        return maxima * passo / aquecer
    fracao = (passo - aquecer) / (total - aquecer)
    return maxima * 0.5 * (1 + math.cos(math.pi * fracao))
for passo in [0, 50, 100, 550, 1000]:
    print(passo, f"{taxa(passo):.6f}")

