import numpy as np
trechos = ["A biblioteca abre às 8h e fecha às 22h.", "O restaurante fica no térreo.", "A matrícula vai até 15 de março."]
pergunta = "Que horas a biblioteca fecha?"
def palavras(texto):
    return texto.lower().replace("?", "").replace(".", "").split()
lista = sorted(set(palavras(" ".join(trechos + [pergunta]))))
def vetor(texto):
    return np.array([palavras(texto).count(p) for p in lista], dtype=float)
def cosseno(a, b):
    return a @ b / (np.linalg.norm(a) * np.linalg.norm(b))
notas = [cosseno(vetor(t), vetor(pergunta)) for t in trechos]
print(np.round(notas, 2).tolist())
print("Contexto:", trechos[int(np.argmax(notas))])
